245	// CLI: `node converge-wiring.mjs [owner/repo] [--badges]` — converge THIS repo's
246	// wiring. The full name comes from argv or GITHUB_REPOSITORY/CLAUDINITE_REPO; the
247	// scheduler stub from the vendored mount. This is the single surface bootstrap
248	// (Part 6) and baselining both invoke, so the wiring set is defined once, here —
249	// with `--badges` the one thing that differs between them: bootstrap passes it to
250	// seed the README pack row, the nightly leaves the README alone.
251	async function main() {
252	  const argv = process.argv.slice(2);
253	  const badges = argv.includes('--badges');
254	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
255	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
256	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
257	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
258	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
259	  const secretNames = await declaredSecrets(root, await repoConfig(root));
260	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges });
261	  if (error) console.log(`! ${error}`);
262	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
263	}
264	
265	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
