274	  let taskScheduler = null;
275	  if (raw.taskScheduler !== undefined) {
276	    if (raw.taskScheduler === null || typeof raw.taskScheduler !== 'object' || Array.isArray(raw.taskScheduler)) {
277	      errors.push({ what: '"taskScheduler" must be an object', fix: 'e.g. { "dailyHour": 4, "weeklyDay": "Sun", "monthlyDay": 1 }' });
278	    } else {
279	      for (const key of Object.keys(raw.taskScheduler)) {
280	        if (!SCHEDULE_KEYS.includes(key)) {
281	          errors.push({ what: `unknown "taskScheduler" setting "${key}"`, fix: `remove it or fix the name — valid taskScheduler settings: ${SCHEDULE_KEYS.join(', ')}` });
