483	    // Merge commits the current change introduces — those on HEAD's first-parent
484	    // chain since the merge-base with the base branch (the squash-only effect
485	    // check, scoped to the work). Empty when no base resolves or the branch is
486	    // even with it; pre-existing merges already on the base are out of range.
487	    //
488	    // The range alone trusts the merge-base to be right, and it isn't always: a
489	    // shallow clone's grafted boundary or a criss-cross history can hand back a
490	    // merge-base that sweeps the base branch's own merges into the range. So each
491	    // candidate is confirmed against the base ref itself — a merge already on the
492	    // base branch was never introduced here, whatever the range says. Offline and
493	    // exact, and it holds when refreshBaseRef couldn't run.
494	    introducedMergeCommits() {
495	      if (!mergeBase) return [];
496	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
497	      return lines(out).map((l) => {
498	        const i = l.indexOf(' ');
499	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
500	      }).filter(({ sha }) => !onBaseBranch(sha));
501	    },
502	
503	    // Fixed-string search across tracked files; git grep exits 1 on no match.
504	    // The vendored shared mount is structurally out of the sweep (canon-owned,
505	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
506	    // excluded here exactly as it is from the scanned file set above: a hit
507	    // inside it must never become a finding.
508	    grepTracked(needle) {
509	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
510	      return lines(out).map((l) => {
511	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
512	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
513	      }).filter(Boolean);
514	    },
515	  };
516	}
517	
518	export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));
